<script setup>
import {ref,onMounted} from 'vue';
import {UserManager,WebStorageStateStore} from 'oidc-client-ts';
const orders=ref([]),product=ref('Notebook'),quantity=ref(1),message=ref(''),report=ref(null),identity=ref('alice'),signedIn=ref(false);
let config,manager,user;
async function headers(){return config.mode==='local'?{'X-Lab-User':identity.value}:{Authorization:`Bearer ${(await manager.getUser())?.access_token??''}`};}
async function api(path,options={}){const r=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...await headers(),...options.headers}});if(!r.ok)throw Error(`${r.status}: ${await r.text()}`);return r.json();}
async function run(fn){try{message.value='';await fn();}catch(e){message.value=e.message;}}
async function load(){orders.value=await api('/orders');}
async function create(){await api('/orders',{method:'POST',body:JSON.stringify({product:product.value,quantity:quantity.value})});await load();}
async function login(){await manager.signinRedirect();}
async function logout(){await manager.removeUser();signedIn.value=false;orders.value=[];window.location.assign(`${config.domain}/logout?client_id=${encodeURIComponent(config.clientId)}&logout_uri=${encodeURIComponent(location.origin+'/')}`);}
async function upload(event){const file=event.target.files[0];if(!file)return;const p=await api('/uploads',{method:'POST',body:JSON.stringify({content_type:file.type,bytes:file.size})});const r=await fetch(p.url,{method:'PUT',headers:p.headers,body:file});if(!r.ok)throw Error('S3 upload failed '+r.status);await api(`/uploads/${p.id}/verify`,{method:'POST'});message.value='Ảnh đã được xác minh; ảnh gốc vẫn ở vùng riêng tư.';}
async function requestReport(){report.value=await api('/reports',{method:'POST',body:JSON.stringify({key:crypto.randomUUID()})});}
async function poll(){report.value=await api('/reports/'+report.value.id);}
async function download(){const data=await api(`/reports/${report.value.id}/download`);const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='report.json';a.click();URL.revokeObjectURL(url);}
onMounted(()=>run(async()=>{config=await (await fetch('/api/config')).json();if(config.mode==='local'){signedIn.value=true;await load();return;}manager=new UserManager({authority:config.issuer,client_id:config.clientId,redirect_uri:location.origin+'/',response_type:'code',scope:'openid '+config.scope,userStore:new WebStorageStateStore({store:sessionStorage}),automaticSilentRenew:true});if(new URLSearchParams(location.search).has('code')){await manager.signinRedirectCallback();history.replaceState({},'',location.pathname);}user=await manager.getUser();signedIn.value=!!user&&!user.expired;if(signedIn.value)await load();}));
</script>
<template><main><h1>Đơn hàng · AWS lab</h1><p>Ứng dụng thực hành với dữ liệu giả.</p><button v-if="!signedIn" @click="run(login)">Đăng nhập Cognito</button><template v-else><label v-if="config?.mode==='local'">Identity local <select v-model="identity" @change="run(load)"><option>alice</option><option>bob</option></select></label><button v-else @click="run(logout)">Đăng xuất</button><form @submit.prevent="run(create)"><label>Sản phẩm <input v-model="product" maxlength="120" required></label><label>Số lượng <input v-model.number="quantity" type="number" min="1" max="100"></label><button>Tạo đơn</button></form><ul><li v-for="order in orders" :key="order.id">{{order.product}} × {{order.quantity}} <small>{{order.id}}</small></li></ul><label>Upload ảnh <input type="file" accept="image/png,image/jpeg" @change="e=>run(()=>upload(e))"></label><p><button @click="run(requestReport)">Xuất báo cáo</button></p><div v-if="report"><p>{{report.id}} — {{report.status}}</p><button @click="run(poll)">Kiểm tra trạng thái</button><button v-if="report.status==='complete'" @click="run(download)">Tải JSON</button></div></template><p role="status">{{message}}</p></main></template>
<style>body{font:16px system-ui;background:#f5f6f8;color:#172033}main{max-width:800px;margin:3rem auto;padding:2rem;background:white;border-radius:12px}label{display:block;margin:1rem 0}button,input,select{font:inherit;padding:.5rem;margin:.2rem}small{display:block;color:#566}button{cursor:pointer}</style>
